function fs(){const n=new Date(),m=n.getHours()*60+n.getMinutes(),W=S.fast.w.map(x=>[mm(x.s),mm(x.e)]).filter(x=>x[0]!=x[1]),win=W.reduce((a,x)=>a+(x[1]-x[0]+1440)%1440,0);let c=null,nx=1440,pv=1440;
if(!W.length)return{inW:true,left:0,len:1,win:1440,pct:0};
W.forEach(x=>{const len=(x[1]-x[0]+1440)%1440,el=(m-x[0]+1440)%1440;if(el<len)c={left:len-el,len,el};nx=Math.min(nx,(x[0]-m+1440)%1440||1440);pv=Math.min(pv,(m-x[1]+1440)%1440)});
if(c)return{inW:true,left:c.left,len:c.len,win,pct:c.el/c.len*100};
return{inW:false,left:nx,len:nx+pv,win,pct:pv/(nx+pv)*100}}
