const renPlan=id=>{const p=PL().find(x=>x.id==id),n=prompt('Nome:',p.n);if(n){p.n=clean(n)||p.n;save();render()}};
const delPlan=id=>{if(confirm('Apagar este arquivo?')){S.plans=PL().filter(x=>x.id!=id);ph('del','w'+id);save();render()}};
const embed=u=>{let m;if(m=u.match(/open\.spotify\.com\/(?:intl-[a-z]+\/)?(playlist|album|track|artist|show|episode)\/([A-Za-z0-9]+)/))return 'https://open.spotify.com/embed/'+m[1]+'/'+m[2];if(m=u.match(/[?&]list=([\w-]+)/))return 'https://www.youtube.com/embed/videoseries?list='+m[1];if(m=u.match(/(?:youtu\.be\/|[?&]v=)([\w-]{6,})/))return 'https://www.youtube.com/embed/'+m[1];return ''};
function vMusica(){const P=S.pl||(S.pl=[]);return `<h1>Música</h1><p style="color:var(--m)">Salve playlists do Spotify ou YouTube e toque aqui dentro, com a lista e o botão de próxima.</p><button class=pri style="width:100%;margin:10px 0" onclick=plAdd()>+ Adicionar playlist (colar link)</button>`+P.map((p,i)=>{const e=embed(p.u);return `<div class="card row sp"><span onclick="PS=${i};render()" style="flex:1">🎵 ${esc(p.n)}</span><button onclick="plOpen(${i})">↗</button><button onclick="plDel(${i})">🗑</button></div>${i==PS&&e?`<iframe src="${e}" style="width:100%;height:${e.includes('spotify')?380:260}px;border:0;border-radius:14px" allow="encrypted-media;autoplay"></iframe>`:''}`}).join('')}
const plAdd=()=>{const u=prompt('Cole o link da playlist (Spotify ou YouTube):');if(!u)return;const n=clean(prompt('Nome da playlist:','Treino'))||'Playlist';(S.pl=S.pl||[]).push({n,u:u.trim()});save();PS=S.pl.length-1;render()};
const plDel=i=>{S.pl.splice(i,1);PS=-1;save();render()};
const plOpen=i=>{location.href=S.pl[i].u};
// ---- semana e mês
const l2=d=>d.slice(8)+'/'+d.slice(5,7);
function vResumo(){const n=new Date(),b=[];let ttl;
if(RM=='sem'){const s=new Date(n.getFullYear(),n.getMonth(),n.getDate()+RO*7-n.getDay());for(let i=0;i<7;i++)b.push(dk(new Date(s.getFullYear(),s.getMonth(),s.getDate()+i)));ttl=l2(b[0])+' – '+l2(b[6])}
else{const m=new Date(n.getFullYear(),n.getMonth()+RO,1),c=new Date(m.getFullYear(),m.getMonth()+1,0).getDate();for(let i=1;i<=c;i++)b.push(dk(new Date(m.getFullYear(),m.getMonth(),i)));ttl=m.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}
const r=b.map(d=>({d,t:tot(d),g:gk(d),x:xs(d)})),lg=r.filter(x=>x.t[0]>0),sm=i=>r.reduce((a,x)=>a+x.t[i],0),av=i=>lg.length?Math.round(sm(i)/lg.length):0,over=lg.filter(x=>x.t[0]>x.g*1.05).length,burn=r.reduce((a,x)=>a+x.x[1],0),why={},mxv=Math.max(...r.map(x=>Math.max(x.t[0],x.g)),1);
r.forEach(x=>((S.days[x.d]||{}).why||{r:[]}).r.forEach(w=>why[w]=(why[w]||0)+1));
const st=(v,l)=>`<div style="flex:1;min-width:30%"><div class=big style="font-size:22px">${v}</div><small>${l}</small></div>`;
return `<div class="row sp" style="margin-bottom:10px"><button onclick="RO--;render()">‹</button><b style="text-align:center">${ttl}</b><button onclick="RO++;render()">›</button></div><div class=row style="margin-bottom:10px"><button class="${RM=='sem'?'pri':''}" style="flex:1" onclick="RM='sem';RO=0;render()">Semana</button><button class="${RM=='mes'?'pri':''}" style="flex:1" onclick="RM='mes';RO=0;render()">Mês</button></div>`+
`<div class=card><h2>Calorias</h2><div class=row style="flex-wrap:wrap;gap:14px">${st(Math.round(sm(0)),'total kcal')}${st(av(0),'média por dia')}${st(over,'dias acima da meta')}${st(Math.round(burn),'kcal em treino')}</div><div class=row style="align-items:flex-end;height:110px;gap:${r.length>10?2:6}px;margin-top:16px">${r.map(x=>`<div style="flex:1;text-align:center"><div style="height:${Math.max(3,x.t[0]/mxv*90)}px;background:${x.t[0]>x.g*1.05?'var(--r)':'var(--t)'};border-radius:3px;opacity:${x.t[0]?1:.15}"></div>${r.length<10?'<small>'+'DSTQQSS'[new Date(x.d+'T12:00').getDay()]+'</small>':''}</div>`).join('')}</div></div>`+
`<div class=card><h2>Média dos macros (dias com registro)</h2>${bar(av(1),S.g.p,'var(--a)','Proteína')}${bar(av(2),S.g.c,'var(--y)','Carbo')}${bar(av(3),S.g.f,'var(--r)','Gordura')}</div>`+
(Object.keys(why).length?`<div class=card><h2>Motivos de passar da meta</h2>${Object.entries(why).sort((a,b)=>b[1]-a[1]).map(x=>`<div class="row sp" style="margin:6px 0"><span>${x[0]}</span><b>${x[1]}x</b></div>`).join('')}</div>`:'')}
// ---- calendário do celular
const CAL=()=>C().CapacitorCalendar;
async function calSync(){const P=CAL();if(!P)return toast('Disponível só no app instalado');try{const a=await P.requestFullCalendarAccess();if(a.result!='granted')return toast('Permissão negada');S.calOn=1;save();await calLoad();render()}catch(e){toast('Não consegui acessar o calendário')}}
async function calLoad(){const P=CAL();if(!P||!S.calOn)return;try{const y=CM.getFullYear(),m=CM.getMonth(),r=await P.listEventsInRange({from:new Date(y,m,1).getTime(),to:new Date(y,m+1,1).getTime()});EV={};(r.result||[]).forEach(e=>{const d=dk(new Date(e.startDate));(EV[d]=EV[d]||[]).push(e)});render()}catch(e){}}
async function calAdd(){const P=CAL();if(!P||!S.calOn)return toast('Sincronize primeiro');if(!confirm('Criar os horários de comer dos próximos 7 dias no seu calendário?'))return;try{const n=new Date();let c=0;for(let i=0;i<7;i++){const d0=new Date(n.getFullYear(),n.getMonth(),n.getDate()+i);if(!S.fast.days.includes(d0.getDay()))continue;for(const w of S.fast.w){const s=mm(w.s),e=mm(w.e);await P.createEvent({title:'🍽️ Janela de comer',startDate:d0.getTime()+s*6e4,endDate:d0.getTime()+(e<=s?e+1440:e)*6e4});c++}}toast(c+' eventos criados');calLoad()}catch(e){toast('Não consegui criar os eventos')}}
function dayCard(){const d=CD,t=tot(d),a=S.days[d]||{todo:{}},dn=S.tasks.filter(x=>a.todo[x.id]).length;return `<div class=card><h2>${lbl(d)}</h2><div class="row sp"><span>🍽️ ${Math.round(t[0])} / ${gk(d)} kcal</span><span>✅ ${dn}/${S.tasks.length}</span></div>${a.why&&a.why.r.length?'<p style="margin-top:8px"><small>Motivo: '+a.why.r.join(', ')+'</small></p>':''}${(EV[d]||[]).map(e=>`<p style="margin-top:8px">📅 ${esc(e.title||'Evento')}<br><small>${new Date(e.startDate).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></p>`).join('')}<div class=row style="margin-top:12px"><button onclick="D='${d}';go('dieta')">Diário</button><button onclick="D='${d}';go('tarefas')">Tarefas</button></div></div>`}
const calCard=()=>`<div class=card><h2>Calendário do celular</h2>${S.calOn?'<div class=row><button onclick=calLoad()>↻ Atualizar</button><button onclick=calAdd()>+ Meus horários de comer</button></div>':'<button class=pri onclick=calSync()>Sincronizar com meu calendário</button>'}<p style="margin-top:8px"><small>Mostra seus eventos aqui e cria os horários de comer no seu calendário.</small></p></div>`;
// ---- backup
const bkJ=()=>JSON.stringify(S);
function bkSheet(){sheet(`<h2>Backup</h2><p style="font-size:13px;margin-bottom:10px;color:var(--m)">Fotos e arquivos de treino não entram no backup.</p><div class=row style="flex-wrap:wrap"><button class=pri onclick=bkShare()>Compartilhar / salvar</button><button onclick=bkCopy()>Copiar</button></div><h2 style="margin-top:20px">Restaurar</h2><textarea id=bkt rows=4 placeholder="Cole o backup aqui"></textarea><label style="display:block;margin:8px 0;font-size:13px;color:var(--m)">ou escolha o arquivo<input type=file accept=".json,.txt,application/json,text/plain" onchange="bkFile(this)"></label><button class=pri style="width:100%" onclick=bkRestore()>Restaurar agora</button>`)}
async function bkShare(){try{await C().Share.share({title:'Backup Jejum e Dieta',text:bkJ(),dialogTitle:'Salvar backup'})}catch(e){toast('Use o botão Copiar')}}
function bkCopy(){try{const t=document.createElement('textarea');t.value=bkJ();document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(ok)return toast('Backup copiado')}catch(e){}navigator.clipboard?navigator.clipboard.writeText(bkJ()).then(()=>toast('Backup copiado'),()=>toast('Use Compartilhar')):toast('Use Compartilhar')}
const bkFile=el=>{const f=el.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{$('#bkt').value=r.result};r.readAsText(f)};
const bkRestore=()=>{try{const o=JSON.parse($('#bkt').value.trim());if(!o||!o.days)throw 0;S=Object.assign({},def,o);fixS();save();closeS();render();toast('Backup restaurado')}catch(e){toast('Backup inválido: cole o texto completo')}};
calLoad();
render();sched();setInterval(()=>{if(tab=='hoje'&&!$('.sheet'))render()},30000);
